ACOORD="Playhead/Services/AnalysisCoordinator/AnalysisCoordinator.swift"
# playhead-mk6z: the BGTask scheduling/handler surface.
BGPS="Playhead/Services/AnalysisCoordinator/BackgroundProcessingService.swift"
