  "KZ04|283|DLMGR|$T_KKZU_BLANK"
  "KZ05|284|DLMGR|$T_KKZU_NAMED"
  "KZ06|285|BGFEED|$T_KKZU_AUTO"
  "KZ07|286|BGFEED|$T_KKZU_AUTO"
  "KZ08|287|EPPREP|$T_KKZU_PREPARE"
  "KZ09|288|FQSCAN|$T_KKZU_FORCE_QUIT"
